"""Full frozen Row semantic bundle; preparation never launches native UI."""
from pathlib import Path
import sys,json,hashlib,shutil,plistlib,shlex
r=Path(__file__).resolve().parents[2];manifest=Path(sys.argv[1]).resolve();m=json.loads(manifest.read_text());assert m['owner']=='preflight'and m['component']=='capabilityrow'and m['runtime']=='osx-arm64'and m['buildExitCode']==0
binary=Path(m['binary']);assert hashlib.sha256(binary.read_bytes()).hexdigest()==m['binarySha256'];bundle=manifest.parent/'CapabilityRowSemanticCheck.app';assert not bundle.exists();mac=bundle/'Contents/MacOS';shutil.copytree(binary.parent,mac/'runtime');out=manifest.parent/'actual-macos-semantic';out.mkdir();(out/'cases.json').write_bytes((r/'docs/replica/source/capabilityrow-table-semantic-source.json').read_bytes())
(mac/'CapabilityRowSemanticCheck').write_text('#!/bin/sh\nexec '+shlex.quote(str(mac/'runtime/ReplicaProbe'))+' --capabilityrow-window '+shlex.quote(str(out/'cases.json'))+' '+shlex.quote(str(out))+' --table-semantic-only'+(' --semantic-lifecycle-only'if '--lifecycle' in sys.argv else '')+' >'+shlex.quote(str(out/'probe.log'))+' 2>&1\n');(mac/'CapabilityRowSemanticCheck').chmod(0o755)
(bundle/'Contents/Info.plist').write_bytes(plistlib.dumps({'CFBundleIdentifier':'local.dbmv.replica.capabilityrowsemanticcheck','CFBundleExecutable':'CapabilityRowSemanticCheck','CFBundleName':'CapabilityRowSemanticCheck','CFBundlePackageType':'APPL','NSHighResolutionCapable':True}));(out/'bundle.json').write_text(json.dumps({'manifest':str(manifest),'bundle':str(bundle),'output':str(out),'nativeBinarySha256':m['binarySha256']},indent=2)+'\n');print(bundle)
